import { test, expect } from '@playwright/test';

test.describe('Breadcrumbs Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display breadcrumbs on product detail page', async ({ page }) => {
    // Navigate to a product detail page
    await page.getByRole('link', { name: /products/i }).click();
    await page.waitForURL(/\/products/);

    // Click on a specific product
    await page.getByRole('link', { name: /laptop/i }).first().click();
    await page.waitForURL(/\/products\/\d+/);

    // Verify breadcrumbs are visible
    const breadcrumbs = page.getByRole('navigation', { name: /breadcrumb/i });
    await expect(breadcrumbs).toBeVisible();

    // Verify breadcrumb items
    const homeLink = breadcrumbs.getByRole('link', { name: /home/i });
    const productsLink = breadcrumbs.getByRole('link', { name: /products/i });
    const currentPage = breadcrumbs.getByText(/laptop/i);

    await expect(homeLink).toBeVisible();
    await expect(productsLink).toBeVisible();
    await expect(currentPage).toBeVisible();
  });

  test('should navigate to parent pages via breadcrumbs', async ({ page }) => {
    // Navigate to a nested page
    await page.getByRole('link', { name: /products/i }).click();
    await page.waitForURL(/\/products/);

    await page.getByRole('link', { name: /electronics/i }).click();
    await page.waitForURL(/\/products\/electronics/);

    await page.getByRole('link', { name: /laptop/i }).first().click();
    await page.waitForURL(/\/products\/electronics\/\d+/);

    // Click on Products breadcrumb to navigate back
    const breadcrumbs = page.getByRole('navigation', { name: /breadcrumb/i });
    await breadcrumbs.getByRole('link', { name: /products/i }).click();

    // Verify navigation to products page
    await expect(page).toHaveURL(/\/products$/);
  });

  test('should display correct breadcrumb hierarchy for category pages', async ({ page }) => {
    // Navigate to category page
    await page.getByRole('link', { name: /categories/i }).click();
    await page.waitForURL(/\/categories/);

    await page.getByRole('link', { name: /electronics/i }).click();
    await page.waitForURL(/\/categories\/electronics/);

    // Verify breadcrumb structure
    const breadcrumbs = page.getByRole('navigation', { name: /breadcrumb/i });
    const breadcrumbItems = breadcrumbs.getByRole('listitem');

    await expect(breadcrumbItems).toHaveCount(3); // Home > Categories > Electronics

    // Verify breadcrumb text content
    await expect(breadcrumbs).toContainText('Home');
    await expect(breadcrumbs).toContainText('Categories');
    await expect(breadcrumbs).toContainText('Electronics');
  });

  test('should show current page as non-clickable in breadcrumbs', async ({ page }) => {
    // Navigate to a specific page
    await page.getByRole('link', { name: /about/i }).click();
    await page.waitForURL(/\/about/);

    // Get breadcrumbs
    const breadcrumbs = page.getByRole('navigation', { name: /breadcrumb/i });

    // Find the current page item (should not be a link)
    const currentPageItem = breadcrumbs.getByText(/about/i);

    // Verify it's not a clickable link
    const parentElement = currentPageItem.locator('..');
    await expect(parentElement).not.toContainText('href');
  });

  test('should maintain breadcrumbs when refreshing page', async ({ page }) => {
    // Navigate to a nested page
    await page.getByRole('link', { name: /products/i }).click();
    await page.waitForURL(/\/products/);

    await page.getByRole('link', { name: /laptop/i }).first().click();
    await page.waitForURL(/\/products\/\d+/);

    // Get initial breadcrumbs
    const breadcrumbs = page.getByRole('navigation', { name: /breadcrumb/i });
    const initialBreadcrumbText = await breadcrumbs.textContent();

    // Refresh the page
    await page.reload();
    await page.waitForLoadState('networkidle');

    // Verify breadcrumbs are still present with same content
    const refreshedBreadcrumbs = page.getByRole('navigation', { name: /breadcrumb/i });
    const refreshedBreadcrumbText = await refreshedBreadcrumbs.textContent();

    expect(refreshedBreadcrumbText).toBe(initialBreadcrumbText);
  });

  test('should display breadcrumbs with proper separators', async ({ page }) => {
    // Navigate to a product page
    await page.getByRole('link', { name: /products/i }).click();
    await page.waitForURL(/\/products/);

    await page.getByRole('link', { name: /laptop/i }).first().click();
    await page.waitForURL(/\/products\/\d+/);

    // Verify breadcrumbs container exists and has proper structure
    const breadcrumbs = page.getByRole('navigation', { name: /breadcrumb/i });
    const breadcrumbList = breadcrumbs.getByRole('list');

    await expect(breadcrumbList).toBeVisible();

    // Verify separator elements exist between breadcrumb items
    const separators = breadcrumbs.locator('[aria-hidden="true"]');
    const separatorCount = await separators.count();

    expect(separatorCount).toBeGreaterThan(0);
  });
});
